quests[52294] = { id = 52294, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fallen Idols", description = "Little creature, please... listen to me. \n\nI am Krag'wa. \n\nOnce, my worshipers were many and my powers great. Now, my followers are all but gone. What little power I have left was placed within several idols, but the idols have been stolen by the heretical blood trolls.\n\nI ask you, please recover my idols so that I can become whole once more!", objectives = "Collect Stolen Idols of Krag'wa from the blood troll camp in the Frogmarsh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
