quests[52305] = { id = 52305, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nature Versus Nurture", description = "Greetings, {name}. I am Wingminder Goja.\n\nI overheard the ordeal that Pa'ku has laid at your feet. I can help you.\n\nI oversee this roost at my loa's pleasure. I have seen many eggs become glorious beasts of war. It will be a long road ahead, with many trials to overcome, but de companionship of a pterrordax be a worthy reward.\n\nFor now, de little one is young. Simply tend to his needs while he stays in de nest. When he is ready to take on de world he will let you know.\n\nGood luck, {name}.", completion = "<Kua'fon opens his wings and screeches gleefully at you!>\n\nSkree!!", objectives = "Tend to Kua'fon until he is ready to fly.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
