quests[52308] = { id = 52308, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Intercepted Orders", progress = "We cannot afford a distraction... or a missed opportunity.", completion = "It's decided, then. The assassination of Blood Prince Dreven at sea will be unexpected, demoralizing, and beneficial to the long-term success of our larger campaign.\n\n<Halford Wyrmbane smiles.>\n\nEverything I'm looking for in a strategy.", objectives = "Discuss the plan with Alliance leadership.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
