quests[52310] = { id = 52310, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corrupted Tideskipper" }
quests[52311] = { id = 52311, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sweete's Strongbox", description = "You've got the keys, and Taelia's still watching our backs. So let's head up to Sweete's, ah, \"office\" and liberate the documents in that strongbox.\n\nCome on, it's across the bridge with the rest of his treasure.", completion = "I'm certain the information we need is in this chest. But given the added security, my backup plan of having Taelia bust this thing open isn't going to work. Who knows what other security is set up on this chest?\n\nWe need to get that final key.", objectives = "Open Harlan Sweete's Strongbox.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52312] = { id = 52312, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Extinguish the Lights" }
quests[52313] = { id = 52313, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission Report: Mudfisher Cove", description = "Your followers have sent a report regarding the assault on Mudfisher Cove.\n\nIt details that victory was hard-fought, but all of the guards previously defending the outpost have been slain.\n\nDeliver the report to Nathanos Blightcaller aboard The Banshee's Wail.", progress = "Do you have news regarding the mission to Drustvar?", completion = "It seems the mission to create an additional foothold in Drustvar was a success. Well done, {name}.\n\nI will send you to oversee the fortifications at once.", objectives = "Deliver the victory report to Nathanos Blightcaller.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52314] = { id = 52314, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mudfisher Cove", description = "The raid you planned for Mudfisher Cove in Drustvar was successful. Well done.\n\nThe outpost is ready to be claimed.\n\nMake your way to Mudfisher Cove in Drustvar and establish fortifications there.\n\nThe cove will be an essential outpost in our campaign against the Alliance.\n\nMove quickly!", completion = "Throm-Ka, {name}. This is a fine location for an outpost! Thanks to your leadership the Horde has yet another foothold in Drustvar!", objectives = "Claim Mudfisher Coast for the Horde.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
