quests[52317] = { id = 52317, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Ptake, Only Throw", description = "<Kua'fon places a troll skull into your palm. It is covered in teeth marks and rather slimy.>\n\nSkree!\n\n<Kua'fon peers at you expectantly.>", completion = "<Kua'fon's eyes shine brightly. He tucks his troll skull safely under a wing and gargles appreciatively at you.>\n\nSkree.", objectives = "Throw Kua'fon's favorite skull.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52319] = { id = 52319, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission Report: Windfall Cavern", description = "Your followers have sent a report regarding the assault on Windfall Cavern.\n\nIt details that victory was hard-fought, but Gravemaul has been slain.\n\nDeliver the report to Nathanos Blightcaller aboard The Banshee's Wail.", progress = "Do you have news regarding the mission to Stormsong Valley?", completion = "It seems the mission to create an additional foothold in Stormsong Valley was a success. Well done, {name}.\n\nI will send you to oversee the fortifications at once.", objectives = "Deliver the victory report to Nathanos Blightcaller.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52320] = { id = 52320, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Windfall Cavern", description = "The raid you planned for Windfall Cavern in Stormsong Valley was successful. Well done.\n\nThe outpost is ready to be claimed.\n\nMake your way to Windfall Cavern in Stormsong Valley and establish fortifications there.\n\nWindfall Cavern will be an essential outpost in our campaign against the Alliance.\n\nGo with honor!", completion = "Well met, {name}. This is a fine location for an outpost! Thanks to your leadership the Horde has yet another foothold in Stormsong Valley!", objectives = "Claim Windfall Cavern for the Horde.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
