quests[52427] = { id = 52427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Work Order: Battle Flag: Rallying Swiftness", progress = "Are you here to deliver supplies?", completion = "Thank you for assisting us, tailor. We needed these battle flags badly." }
quests[52428] = { id = 52428, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infusing the Heart", description = "Azeroth's voice is growin' fainter and fainter. If the seal on this chamber shatters, her soul will be lost!\n\nWe've got one chance tae save us all.\n\nAbsorb the Azerite around the chamber into the Heart of Azeroth. Then unleash the amulet's power tae seal that crack in the center of the seal.\n\nAzerite can be a destructive force, but if it's channeled through yer amulet, it can heal the world!", progress = "What are ye waitin' fer?", completion = "That was too close, {name}! Now ye've seen the true power of the Heart of Azeroth. \n\nBut we've got a long way tae go before the world is healed.", objectives = "Absorb Azerite to empower the Heart of Azeroth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52430] = { id = 52430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not So Bad Down Here", objectives = "Defeat Grixis Tinypop in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52431] = { id = 52431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No-Landing Zone", description = "These pirates are ruthless - they're bringing in landing boats to cut off our escape!\n\nThe guards are down at the riverside holding them off, but I'm afraid they'll be overrun before my family and I can get away!", progress = "Please help the guards fend off those pirates!", completion = "Oh thank you, thank you so much!", objectives = "Slay Burnsy the Blade, Wiley Jaki, and Skullcrusher Cotner.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52432] = { id = 52432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Squall" }
quests[52436] = { id = 52436, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blackwood Den", description = "We have not moved all of our troops into Darkshore yet, but I think we have enough to justify establishing a foothold somewhere. I know just the place.\n\nJust south of here is the Blackwood Den. Its inhabitants, the Furbolgs, have been driven in to a hysteria. With our enemies pouring from the North, the Furbolg threat is a nuisance we cannot afford. \n\nI will lead another squad past the wall while you... negotiate with the Furbolgs.", completion = "Just you wait, {name} -- once we have conquered Darnassus the Elders of the Blackwood tribe will be thanking us for restoring peace to the den.\n\nWe just need to borrow it for a moment.", objectives = "Drive the furbolgs out of the Blackwood Den.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52437] = { id = 52437, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Start of Something Good", description = "While the rest of our army sets up camp -- you should follow me. I spotted something... interesting... on my way back from Zoram'gar.\n\nI'll admit, not even I could have predicted such fortuitous happenstance.\n\nCome with me, {name}. And bring a pickaxe.", completion = "You heard the warchief, we got work to do!", objectives = "Follow Sylvanas to Nazj'vel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52438] = { id = 52438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Wild Ride", description = "Let me tell ya, kid... this may be some of the best work I've ever done!\n\nNow that the upgrades are in place, there's no time to waste.\n\nThe battle is raging over at Wildbend River. Take the modified hellion into battle and give 'em hell!", completion = "For every enemy we slay, two replace them on the battlefield...", objectives = "Join the battle at Wildbend River.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52439] = { id = 52439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iron Stores", description = "While the mine is under Alliance banners our workers ensure the iron supply never runs dry.\n\nThis key will provide access to the stores. Take what you need.", progress = "These old chests can be quite the bother.", completion = "Well now, that was easy.", objectives = "Use the Heavy Iron Key to access the Iron Stores.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52440] = { id = 52440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Resource Recruitment", description = "If we're to maintain our iron supply we'll need a bit of help.\n\nSee if you can wrangle us up a few fresh recruits for the mine.", completion = "Well done. Those recruits will surely help maintain our iron supply.", objectives = "Recruit 3 Highlands Peasants to work.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52443] = { id = 52443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Final Foothold", description = "We have established two critical footholds in Zandalar. The time has come to establish the third.\n\nLet's review the battle plan when you're ready.", completion = "Ready to go? Let's get a move on, then.", objectives = "Use the Zandalar Campaign Map to review the final foothold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52444] = { id = 52444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Final Foothold", description = "We have established two critical footholds in Kul Tiras. The time has come to establish the third.\n\nLet's review the battle plan when you're ready.", completion = "I trust you are sufficiently prepared, then.", objectives = "Use the Kul Tiras Campaign Map to review the final foothold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52445] = { id = 52445, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tol Dagor: The Fourth Key", description = "Hey, wait a second. I know the type of key our fourth lock needs. This is the same sort of lock the Ashvane company uses. Resists lockpicks like nothing else, but they have a standard skeleton key. There was a set hanging on the wall in the Tol Dagor Armory. Given the state we left it in, it'd be easy to grab it.\n\nTaelia and I will take the chest back to the Harbormaster's office for safe keeping. \n\nYou go in to Tol Dagor and get that last key!", progress = "I knew securing that last key wouldn't be a problem for you, {name}!", completion = "Well, you have your answer. Jaina was sent to Fate's End.", objectives = "Enter the Tol Dagor dungeon, recover the Ashvane Skeleton Key and kill Overseer Korgus, then return to Flynn Fairwind in the Harbormaster's Office in Boralus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52446] = { id = 52446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sister Absinthe" }
quests[52447] = { id = 52447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Room To Grow", description = "Ah, I would not worry too much about de little one.\n\nSome beasts take longer than others to find their way, and Kua'fon is no exception.\n\nFor now, continue to help him grow. Keep him fed, keep him out of danger, and strengthen your bond. He will let you know when he is ready to try again.", completion = "<Kua'fon wriggles anxiously, leveling one golden eye upon you.>\n\nSkree?", objectives = "Tend to Kua'fon until he is ready to attempt another flight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52449] = { id = 52449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mysterious Island", description = "Fate's End is just that. It's where the very worst criminals are sent. No one ever comes back.\n\nI'm sorry Lady Katherine will have to hear this, but I'm glad it isn't my job to tell her.\n\n<Flynn hands you the document solemnly.>\n\nI'm certain she'll want an update, even if the news is as bad as this.", completion = "Fate's End! Merciful Tides, I'd hoped she wouldn't have been sent there... But of course she would be.\n\nNo matter. I must forge ahead.", objectives = "Report to Katherine Proudmoore in Boralus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52450] = { id = 52450, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uniting Kul Tiras", objectives = "The people of Kul Tiras are diverse and capable. With their forces loyal to the Alliance, the Horde has no chance of stopping us.\n\nNow, the real work begins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52451] = { id = 52451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uniting Zandalar", objectives = "The people of Zandalar are diverse and capable. With their forces loyal to the Horde, the Alliance has no chance of stopping us.\n\nNow, the real work begins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52452] = { id = 52452, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Song Mistress Dadalea" }
quests[52453] = { id = 52453, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Forlorn Hope", description = "<Lady Katherine's jaw sets.>\n\nI refuse to believe I am too late.\n\nNo one has ever come back from Fate's End, but if anyone could survive I have to believe it would be my Jaina.\n\nGo to Stormsong Valley and secure transit to Fate's End from the tidesages. Brother Pike is a good place to start.\n\nHurry, {name}.", completion = "Jaina Proudmoore was sent to Fate's End and her mother wishes to save her?\n\nThen we must act at once if we are to have any hope of saving her life!", objectives = "Go to Stormsong and speak with Brother Pike at Kraken's Reach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52454] = { id = 52454, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freehold: Dread Captain Vandegrim" }
quests[52455] = { id = 52455, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unbreakable", objectives = "Defeat Grixis Tinypop in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52456] = { id = 52456, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freehold: Veteran Man O' War" }
quests[52458] = { id = 52458, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freehold: Pieces of Eight" }
quests[52459] = { id = 52459, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whirlwing" }
quests[52462] = { id = 52462, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Load of Scrap", description = "Hello, friend. Would you like the scoop on the latest invention of the century?\n\nIt's called the Scrap-O-Matic 1000 and this device can triple, no QUADRUPLE your production capacity as a crafter of armor, weapons or other gizmos you adventurers wander around with.\n\nHere, take these pants and use the Scrap-O-Matic on 'em. You'll get the hang of it.", progress = "This machine is gonna change everything!", completion = "And just like that, you're back in business. All the materials you put into making the item come back to you with the Scrap-O-Matic 1000.\n\nWell, maybe not ALL the materials, but hey, something's better than nothing, right?\n\nOh, and keep an eye out for explusom. It's what we've discovered as a magical byproduct of the scrapping process.\n\nIt's quite potent and only shows up when we scrap really fancy stuff.", objectives = "Use the Scrap-O-Matic 1000 on the pair of Tattered Pants.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52463] = { id = 52463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haegol the Hammer" }
quests[52464] = { id = 52464, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Osca the Bloodied" }
quests[52467] = { id = 52467, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battlefield Scavenging", description = "Our efforts to reclaim the keep have left our supplies a bit lighter than we anticipated. If our forces are to continue, we'll need to restock.\n\nCheck the enemy camps for anything of value. We'll make use of what you find.", progress = "Find anything of interest?", completion = "Pilfering is a dangerous business, though I must admit I am quite impressed.\n\nWe'll be sure to put these supplies to good use.", objectives = "Gather supplies from Newstead, High Perch and the Circle of Elements.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52468] = { id = 52468, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raiding Their Stores", description = "Our rations are low. We need to keep our forces fed if we're to continue our efforts.\n\nBefore it was overrun, Newstead had plenty of food in their stores. I only hope there's something left.You will be able to choose one of these rewards:", objectives = "Obtain a Roast Boar, a Colossal Cheese Wheel, a Basket of Eggs, and a Keg of Applebrew.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52471] = { id = 52471, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That's a Big Carcass", objectives = "Defeat Grixis Tinypop in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52472] = { id = 52472, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Make Loh Go", description = "Hello, {name}! We tortollans grow up hearing the stories of Loh, a tortollan who had many adventures. These stories help to challenge a young tortollan's mind as they try to figure out how Loh would make his way through any given adventure.\n\nCare to give it a try?", completion = "Well done, {name}!", objectives = "Learn how to guide Loh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52473] = { id = 52473, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringing Down the Fleet", description = "This is it, {name}. We've weakened the Horde enough to make a daring strike on Zuldazar itself.\n\nOur forces in Zuldazar still remain hidden, thanks to the help of the Dark Iron dwarves. That gives us our chance to strike.\n\nSet sail to Zuldazar. We will be gathering our forces there for a coordinated strike to weaken their harbor defenses.", completion = "We're all gathered. Let's begin, we cannot afford to lose any more time.", objectives = "Speak with Grand Admiral Jes-Tereth to sail to Zuldazar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52474] = { id = 52474, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Poacher Zane" }
quests[52475] = { id = 52475, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where Eagles Prey" }
quests[52476] = { id = 52476, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lichen King" }
quests[52477] = { id = 52477, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Ayame", description = "Wanted: For the death of twelve pilgrims and their escort to Torga's Rest. A reward is offered to anyone who brings in the head of the great serpent, Ayame. \n\n-Korkush", progress = "Yeah, I put up the poster. Got anything for me?", completion = "It's good to see that snake got what it deserved!\n\nHere's your reward, you earned it.", objectives = "Hunt down Ayame and obtain its head.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52478] = { id = 52478, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission Report: Hillcrest Pasture", description = "Your followers have sent a report regarding the assault on Hillcrest Pasture.\n\nIt details that victory was hard-fought, but the Stormsong defenders have been slain.\n\nDeliver the report to Nathanos Blightcaller aboard The Banshee's Wail.", progress = "Do you have news regarding the mission to Stormsong Valley?", completion = "It seems the mission to create an additional foothold in Stormsong Valley was a success. Well done, {name}.\n\nI will send you to oversee the fortifications at once.", objectives = "Deliver the victory report to Nathanos Blightcaller.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52479] = { id = 52479, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hillcrest Pasture", description = "The raid you planned for Hillcrest Pasture in Stormsong Valley was successful. Well done.\n\nThe outpost is ready to be claimed.\n\nMake your way to Hillcrest Pasture in Stormsong Valley and establish fortifications there.\n\nHillcrest Pasture will be an essential outpost in our campaign against the Alliance.\n\nGo with honor!", completion = "Well met, {name}. This is a fine location for an outpost! Thanks to your leadership the Horde has yet another foothold in Stormsong Valley!", objectives = "Claim Hillcrest Pasture for the Horde.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52480] = { id = 52480, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Ayame", description = "Well equipped exterminator wanted.\n\nHuge snake seen lurking north of Fort Victory. \n\nReward offered for anyone who brings in the head of the pest.\n\n-Garrick Blacksteel", progress = "Got anything fer me?", completion = "Ah! Good! I've nae been able ta sleep a wink since I first saw this thing!\n\nHere's ye reward, ye earned it!", objectives = "Hunt down Ayame and obtain its head.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52481] = { id = 52481, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Of Myth and Fable", description = "If Jaina is truly trapped in the Blighted Lands, that could mean we're not too late! We just need to find a way inside...\n\nWe will need to enlist the help of Lucille Waycrest. The legends of that place are deeply rooted in Drustvar's culture. If anyone would know more about it, it would be she.\n\nI will send a raven ahead for her to prepare what knowledge she can gather. Make haste to Arom's Stand!", completion = "I can't believe you're thinking of intentionally seeking out the Blighted Lands. The legends say it's a terrible place that exists for torment and pain.\n\nI'm not sure any prize is worth treading those grounds.", objectives = "Meet with Lucille Waycrest at Arom's Stand in Drustvar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52482] = { id = 52482, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Old Bear", description = "I cannot change your mind, can I? Very well, I may know where you can find your answers. \n\nHigh in the mountains, there is a hidden alcove of impossibly verdant growth. It is there that the druids of Kul Tiras train in the old ways of the Drust - from before the time of Gorak Tul.\n\nTheir leader is a great bear named Ulfar. I know little about him, but few are more qualified to parse the magic of the Drust.\n\nYou will find a path to his den along Highroad Pass. Good luck, Inquisitor.", progress = "Yes?", completion = "Forgive my hesitation, mainlander. It would appear the minions of Thros are no longer confined to their own realm.\n\nI will help you cross the threshold into the Blighted Lands.", objectives = "Speak with Ulfar in Ulfar's Den.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52483] = { id = 52483, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nightmare Catcher", description = "The effigies crafted by the followers of Gorak Tul were made not of wood, but of the bones and sinew of their enemies. This will be your first task.\n\nTravel to Gol Osigr where the ancient Drust have awoken from their slumber. The bones here belong to Gorak Tul's greatest soldiers who stood with him at the final battle against the first Lord Waycrest.\n\nTheir bones seethe with hatred and anger. This will serve your needs well.", progress = "Do you have the materials?", completion = "I can practically feel the hatred emanating off these bones. They will do nicely.", objectives = "Collect 4 Intact Drust Bones and 9 Ancient Sinew from Drust skeletons in Gol Osigr.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52484] = { id = 52484, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buried Power", description = "Since time immemorial, the Drust have used runes to shape their magics. This remains true of the spells woven by Gorak Tul and his ilk. You will need some of these runes for your effigy to be effective.\n\nIt is likely that some still exist at the site of his final battle, buried under years of soot and snow. \n\nTake this stone. It is empowered with the magic of the Thornspeakers and will react to Tul's spells. With it, you should be able to locate the runes, no matter how deep the ages have buried them.", progress = "What have you uncovered beneath the snows of Gol Osigr?", completion = "These runestones still throb with the twisted energy of Gorak Tul's magic. They will serve you well.", objectives = "Use the Dowsing Stone to find and Collect 6 Drust Runestones in Gol Osigr.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52485] = { id = 52485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hatred's Focus", description = "An effigy requires a central focus. The coven are fond of using animal skulls for this purpose, but for your task you will need something much more potent.\n\nKorvash was a trusted lieutenant to Gorak Tul, as well as a powerful sorcerer, until he was defeated at the battle of Arom's Stand. His bones remain at the site of his demise, now buried by the years.\n\nFind them, and take his skull.", progress = "Have you found Korvash's bones?", completion = "Korvash's skull will make a powerful focus indeed, but the years have drained it of its natural potency.\n\nYou will need to take further steps to prepare it for your ritual.", objectives = "Collect Korvash's Skull from Korvash in Gol Osigr.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52486] = { id = 52486, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waycrest Manor: Draining the Heartsbane", description = "The skull you have taken from Korvash needs to be steeped in Gorak Tul's magic to grant the power needed to bridge the gap to Thros. You must take it to a font of his power, and let it absorb his magic.\n\nYou will find one such font in Waycrest Manor - the epicenter of the coven's power. Here, their leader has tapped so freely into Tul's power that it emanates from the very walls.\n\nBring Korvash's skull to the heart of the manor and let it feast. Then, the effigy will be complete.", completion = "So, this thing is the key to opening the gateway?\n\nYou truly mean to go through with this, then?", objectives = "Empower Korvash's Skull in the depths of Waycrest Manor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52487] = { id = 52487, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into Darkness", description = "I didn't think you would find a way. Though at this point, I guess I shouldn't be surprised when you accomplish what seems impossible.\n\nI guess all that is left is to brave the Crimson Forest and see if this thing works.\n\nFirst, however, Katherine has ordered me to send word when you have found a way to Jaina. You can use one of our falcons to take a message to her.", progress = "We've made it this far. There's no turning back.", completion = "It looks like the effigy's magic is working, but I think there's something we're missing here.", objectives = "Speak with Ensign Josey to send a message to Katherine, then meet her at Gol Inath in the Crimson Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52488] = { id = 52488, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runic Resistance", description = "Whatever is going on with this effigy, I don't think it's going to open the gateway without our help.\n\nThese runes must be the key. There must be some way we can use them to activate the effigy.", progress = "There must be some trick to these runes...", completion = "Remarkable! Yesterday, I believed this place to only exist in tales and legends, and now I stand a footstep away from it...\n\nI just hope that at least some of those tales were exaggerations...", objectives = "Solve the runic puzzle to activate the Drust Effigy in Gol Inath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52489] = { id = 52489, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunting Blood Prince Dreven", progress = "Our strikes will be swift and true. The san'layn will fall.", completion = "The foul weather offers us some cover. Every thick cloud and raindrop is an ally.\n\n<Shandris Feathermoon smirks.>\n\nIn that sense, we actually outnumber the Horde. They don't stand a chance.", objectives = "Ride Swiftwing to accompany Falstad and Shandris to the Great Sea.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52490] = { id = 52490, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Behind Enemy Boats", completion = "Ha! Nathanos is gonna be cryin' all the way back tae Sylvanas's nursery after that whoppin'!\n\nDid ye find Blood Prince Dreven?", objectives = "Search the Banshee's Wail for signs of Blood Prince Dreven.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52491] = { id = 52491, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Broadside Bedlam", description = "<The ship's cannons are currently pointed at the other Forsaken ship across the water.\n\nHowever, it appears the crew hasn't loaded them with gunpowder or cannonballs yet... Probably to avoid any accidental firings while they're anchored here.\n\nYes, it'd be a real shame if \"accidental\" cannon fire damaged the other ship.>", progress = "Ye find anything interesting down in the ship?", completion = "I wish ye could've seen the crew panicking when ye shot off those cannons. It was hilarious!\n\nThat's the Wildhammer style!", objectives = "Collect gunpowder, cannonballs, and a torch, then fire the cannons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52492] = { id = 52492, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wildhammer Specialty", description = "Well, if ye didn't find Blood Prince Dreven on yer ship, he must be hiding on the other one.\n\nI can take ye down to it, but the Horde knows we're here now. What do ye say we create some distractions to hold their attention while we hunt down Dreven?\n\nMe Wildhammers are itchin' tae let the hammers fly. Ye want to join us for the first round?", completion = "He's here.", objectives = "Join Falstad and Swiftwing on a bombing run over the Horde ships.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52493] = { id = 52493, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Unnatural Crew", description = "Blood Prince Dreven is here, and the situation's even worse than we thought.\n\nThat monster's training other san'layn. Every neophyte you see on this ship is another future Blood Prince Dreven.\n\nHis vile practices cannot be allowed to spread within the Horde. We're going to tear the san'layn out, right now, root and all.", progress = "Every san'layn must be felled today, or we'll never be rid of them.", completion = "That is enough for now. We must focus our efforts on Blood Prince Dreven.", objectives = "Kill 12 Horde crew aboard the Crimson Squall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52494] = { id = 52494, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foul Crystals for Foul People", description = "Blood Prince Dreven and his followers are siphoning power from blood-infused crystals to bolster their unholy abilities.\n\nDestroying those crystals will weaken Dreven before we fight him. Take out as many as you can find.", completion = "Good. That should weaken Blood Prince Dreven long enough for us to kill him.", objectives = "Destroy 5 San'layn Crystals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52495] = { id = 52495, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ending the San'layn Threat", description = "Blood Prince Dreven has barricaded himself in the lowest deck of this ship. He's trapped down there.\n\nDon't think that makes this easy for us. A cornered beast is more dangerous than a free one. But, if we have the will and wisdom, he can be slain.\n\nFollow me. I will break the barrier blocking his lair and we will face him together.", completion = "<Shandris raises her eyes to the sky and speaks somberly.>\n\nAnde'thoras-ethil, sisters. Shaha lor'ma.", objectives = "Kill Blood Prince Dreven.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52496] = { id = 52496, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Clean Escape", completion = "You've done the Alliance, and all of Azeroth, a fine service today, {name}.\n\nWe will sleep in a better world than we woke to. That is all that can be asked of us.\n\nFor the Alliance!", objectives = "Return to Boralus and report to High Commander Halford Wyrmbane.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52497] = { id = 52497, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raiding the Boulderfist", description = "The Boulderfist have been rather active ever since the battle began. One of our scouts reported their recent raid on Galson's Lode proved rather lucrative.\n\nScout the cave to the northeast, find the iron ore they stole and steal it back.\n\nWe can't afford to let anyone else control our resources.", objectives = "Obtain 200 pieces of Unprocessed Iron Ore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52504] = { id = 52504, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So We Meat Again" }
quests[52505] = { id = 52505, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pruning the Thorns" }
quests[52506] = { id = 52506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blunt the Spikes" }
quests[52507] = { id = 52507, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sticky Mess" }
quests[52508] = { id = 52508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritual Effects", description = "I will need some assistance in conducting the ritual to allow us to gain passage to Fate's End. To help me with that, you will require the proper items and attire.\n\nNormally I have free access to these things, but the recent upheaval has blocked myself and many of my brothers and sisters from obtaining them easily. However, the fallen tidesages across the span have all you will need.\n\nCollect a ritual knife, lantern and robes from the fallen and these so-called prophets.", progress = "It warms my heart to see these used for good once more.", completion = "Wonderful. These are more than just a costume, they're an essential part of our traditions. For the ritual to work, you'll need to step into the role as fully as you can.", objectives = "Collected a Ritual Knife, Ritual Lantern and Ritual Robes from the Fallen Hullwardens and Abyssal Prophets in Tempest's Edge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52509] = { id = 52509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Strength of the Storm", description = "The ritual I must conduct is written on a scroll. To gain access to it, you'll have to break through the dark energies the fallen tidesages have placed around it, with the power of the storm.\n\nThis relic can be used to pull purified power from the enslaved elementals. Not only will you be gaining the means to our end, you will ultimately be freeing these spirits from corruption.\n\nDefeat the enslaved elementals and then call their power into the relic.", completion = "Well done, {name}. The staff is now imbued with the strength of those elementals. You will need it for what lies ahead.", objectives = "Collected motes of Stormsurge from defeated elementals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52510] = { id = 52510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shrine of the Storm: The Missing Ritual", description = "The ritual which allows safe passage to Fate's End is a closely guarded secret to keep the curious from venturing there and suffering the same fate as the condemned. I have never conducted it before, but there is a scroll with instructions.\n\nIt is held in the Shrine of the Storms. To access the scroll, use the staff you have empowered to break the dark energy surrounding it.\n\nCollect the Ritual of Safe Passage and bring it to me.", progress = "Were you able to recover the Ritual of Safe Passage?", completion = "Good! Time is of the essence if we are to save Lady Jaina. I have made what preparations I can. Allow me a moment to read through the ritual and then we may begin.", objectives = "Go into the Shrine of the Storms, recover the Ritual of Safe Passage and defeat Vol'zith the Whisperer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52511] = { id = 52511, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Opening the Way", description = "Hmm. This ritual is a bit... tricky. No matter, together we will be able to complete it.\n\nI shall begin to channel. You will need to activate the runes in the proper order. I shall leave the scroll here so you may consult it.", progress = "There we are. The clouds clear and the sea calms. Our way is open.", completion = "From here we shall be able to reach Fate's End. Hopefully in time.", objectives = "Complete the ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52512] = { id = 52512, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fate's End", description = "Fate's End is a place in turmoil. The seas froth, the air cracks with thunder. We tried to settle there once, but each settlement disappeared into the mists, every soul never to be seen again. The island did not want inhabitants.\n\nNow we send our most vile exiles there. They never return and no one knows why.\n\nShould we find and recover Jaina, she will be the first. I hope we are not too late.", progress = "By the Tides, I thought we were done for.", completion = "You appeared to leave the island for a brief moment, then reappeared with that creature. Perhaps where it came from is where Jaina has gone.\n\nLady Katherine should be told of this development.", objectives = "Travel to Fate's End and search for signs of Jaina.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52513] = { id = 52513, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost in Darkness", description = "If people are being pulled somewhere else, it would explain why no one has ever returned. I also choose to believe it means Lady Jaina might be able to be saved as well.\n\nGo back to Lady Katherine with all speed! She will want to know of this development.", completion = "The Blighted Lands? Why... I thought that was only a legend used to frighten children.\n\nMy daughter... What have I done to you?", objectives = "Return to Katherine Proudmoore in Boralus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52544] = { id = 52544, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The War Cache", description = "{name}. Let's talk.\n\nThis war won't be won simply by adding the Kul Tirans to our ranks. We eventually need to crush the Horde.\n\nYou and I will be leading an expedition to... disrupt the Horde operations in Zandalar. But first, we need resources.", progress = "Ready to sail when you are, {name}.", completion = "<Halford looks over the gathered resources.>\n\nThis should do it.", objectives = "Gather 100 War Resources. War Resources can be obtained from many sources, including quests and treasure chests.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[52545] = { id = 52545, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Royston Needs Help!" }
